__lazy_modules__ = {"tablib.core", "tablib.plugins"}

try:
    # Generated by setuptools-scm.
    from ._version import version as __version__
except ImportError:
    # Some broken installation.
    __version__ = None


from .core import (  # noqa: F401
    Databook,
    Dataset,
    InvalidDatasetType,
    InvalidDimensions,
    UnsupportedFormat,
    detect_format,
    import_book,
    import_set,
)


def __getattr__(name):
    """Expose ``tablib.plugins`` without paying for it on every import.

    The plugin subsystem pulls in ``importlib.metadata`` and the config parser;
    keeping it lazy means a program that never touches plugins imports exactly
    what it imported before.
    """
    if name == "plugins":
        import importlib

        module = importlib.import_module(".plugins", __name__)
        globals()["plugins"] = module
        return module
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

